/* ledger-ch09.js — Chapter 9's arithmetic, from his own worked example.
 *
 * GENERATED by tools/cma_ledger from the chapter's "Everything ties" box, which is the
 * one place the author writes his numbers out as expressions rather than as results.
 * Each tie below EVALUATES his expression and compares it with the figure he prints, so
 * a mistyped amount anywhere in the chapter's Extended Example fails the gate instead of
 * teaching a wrong total. Do not edit by hand: regenerating is how a correction to the
 * book reaches the site.
 *
 * 3 of the 3 lines in the box are read as arithmetic.
 */
(function (root) {
  "use strict";

  function money(n) {
    var neg = n < 0, s = Math.abs(n).toLocaleString("en-US");
    return neg ? "(" + s + ")" : s;
  }
  function plain(n) { return String(Math.abs(n)); }
  function signed(n) { return n === 0 ? "0" : (n > 0 ? "+" : "\u2212") + Math.abs(n).toLocaleString("en-US"); }
  function arrow(n) { return n === 0 ? "0" : (n > 0 ? "\u2191" : "\u2193"); }

  /* ---- the figures the chapter closes on, in the order he writes them ---- */
  var P = {
    tie1: 120000,          /* Finished goods difference: $756,000 − $636,000 = 60,000 × $2.00 */
    tie2: 80000,          /* Opening difference: $504,000 − $424,000 = 40,000 × $2.00 */
    tie3: 40000,          /* Income difference: $2,946,000 − $2,906,000 = $40,000 */
  };

  function checkTies() {
    function t(label, left, right) {
      return { label: label, left: left, right: right, ok: Math.abs(left - right) < 0.001 };
    }
    return [
      t("Finished goods difference: $756,000 − $636,000 = 60,000 × $2.00", 756000.0 - 636000.0, P.tie1),
      t("Opening difference: $504,000 − $424,000 = 40,000 × $2.00", 504000.0 - 424000.0, P.tie2),
      t("Income difference: $2,946,000 − $2,906,000 = $40,000", 2946000.0 - 2906000.0, P.tie3),
    ];
  }

  root.LEDGER = {
    unit: "USD",
    company: { orontes: "Orontes Foods, Inc.", barada: "Barada Wholesale, Inc." },
    printed: P,
    checkTies: checkTies,
    money: money, plain: plain, signed: signed, arrow: arrow
  };
})(window);
